    "thumbnailSvg": "<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"-30.0 -30.0 1515.0 560.0\" width=\"1515.0\" height=\"560.0\">\n  <defs>\n    <style>\n      @import url(\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&amp;display=swap\");\n      text { font-family: \"Inter\", -apple-system, BlinkMacSystemFont, \"Segoe UI\", Roboto, sans-serif; }\n    </style>\n    <marker id=\"arrowhead\" markerWidth=\"10\" markerHeight=\"7\" refX=\"9\" refY=\"3.5\" orient=\"auto\">\n      <polygon points=\"0 0, 10 3.5, 0 7\" fill=\"#2563EB\" />\n    </marker>\n    <marker id=\"arrowhead-hero\" markerWidth=\"10\" markerHeight=\"7\" refX=\"9\" refY=\"3.5\" orient=\"auto\">\n      <polygon points=\"0 0, 10 3.5, 0 7\" fill=\"#D93829\" />\n    </marker>\n    <marker id=\"arrowhead-danger\" markerWidth=\"10\" markerHeight=\"7\" refX=\"9\" refY=\"3.5\" orient=\"auto\">\n      <polygon points=\"0 0, 10 3.5, 0 7\" fill=\"#DC2626\" />\n    </marker>\n  </defs>\n  <rect x=\"-30.0\" y=\"-30.0\" width=\"1515.0\" height=\"560.0\" fill=\"#F8FAFC\" />\n  <rect x=\"10.0\" y=\"10.0\" width=\"1435.0\" height=\"480.0\" rx=\"0.0\" fill=\"transparent\" stroke=\"#CBD5E1\" stroke-width=\"1.5\" />\n  <text x=\"30.0\" y=\"46.0\" fill=\"#64748B\" font-size=\"11px\" font-weight=\"400\">SKETION TEMPLATE LIBRARY · DISEÑO &amp; UX · INTER VECTORIAL</text>\n  <rect x=\"60.0\" y=\"50.0\" width=\"665.0\" height=\"195.0\" rx=\"6.0\" fill=\"#FFFFFF\" stroke=\"#CBD5E1\" stroke-width=\"1.2\" />\n  <text x=\"80.0\" y=\"81.0\" fill=\"#0F172A\" font-size=\"13px\" font-weight=\"400\">DISTRIBUTED HUMANS</text>\n  <text x=\"80.0\" y=\"111.0\" fill=\"#475569\" font-size=\"11px\" font-weight=\"400\">Async-first, global hiring.\nSaaS-heavy, human-centric workflows.\nLow automation leverage.</text>\n  <rect x=\"745.0\" y=\"50.0\" width=\"665.0\" height=\"195.0\" rx=\"6.0\" fill=\"#FFF5F2\" stroke=\"#D93829\" stroke-width=\"2.0\" />\n  <text x=\"765.0\" y=\"81.0\" fill=\"#D93829\" font-size=\"13px\" font-weight=\"400\">AGENT TEAMS (HERO TARGET)</text>\n  <text x=\"765.0\" y=\"111.0\" fill=\"#475569\" font-size=\"11px\" font-weight=\"400\">Autonomous AI agents execute.\nHumans steer and audit outcomes.\nUltra-high leverage per seat.</text>\n  <rect x=\"60.0\" y=\"260.0\" width=\"665.0\" height=\"195.0\" rx=\"6.0\" fill=\"#FFFFFF\" stroke=\"#CBD5E1\" stroke-width=\"1.2\" />\n  <text x=\"80.0\" y=\"291.0\" fill=\"#0F172A\" font-size=\"13px\" font-weight=\"400\">OFFICE CLASSIC</text>\n  <text x=\"80.0\" y=\"321.0\" fill=\"#475569\" font-size=\"11px\" font-weight=\"400\">Co-located physical desks.\nManual paper and sync meetings.\nLegacy operations baseline.</text>\n  <rect x=\"745.0\" y=\"260.0\" width=\"665.0\" height=\"195.0\" rx=\"6.0\" fill=\"#FFFFFF\" stroke=\"#CBD5E1\" stroke-width=\"1.2\" />\n  <text x=\"765.0\" y=\"291.0\" fill=\"#0F172A\" font-size=\"13px\" font-weight=\"400\">IN-PERSON + AI ASSISTANTS</text>\n  <text x=\"765.0\" y=\"321.0\" fill=\"#475569\" font-size=\"11px\" font-weight=\"400\">Smart offices with edge compute.\nHybrid workforce model.\nHigh tooling cost.</text>\n</svg>"
